from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
import itertools
m=Modulo('P02','Foraminiferi, coppe e campagne','Copertura temporale, confronti appaiati e limiti di quattro repliche')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P02',i,b)
m.sezione_nuova('Fonte e supporto delle osservazioni')
p('Una domanda sulla variazione della taglia',
'''Il progetto esamina il diametro massimo medio di Neogloboquadrina pachyderma in coppe di una trappola sedimentaria della Penisola Antartica occidentale, collocata a 170 metri di profondità. L’estratto PANGAEA conserva trentasei righe del supplemento di Mikis e collaboratori, con date centrali e sintesi morfometriche. La domanda confronta le fasce calendario ottobre–marzo e aprile–settembre nelle campagne che le rappresentano entrambe. Le fasce definiscono un criterio temporale di raggruppamento, del quale occorre distinguere il significato dalle condizioni ambientali effettivamente vissute dagli organismi.''',tikz=d('D01',linea(.6,.7,6.8,.7,'Quantum')+n(3.7,.25,'Superficie marina',w=6,size=11)+r'\draw[Classical,fill=Classical!8,line width=.8pt] (2,2)--(5.4,2)--(4.1,3.4)--(3.3,3.4)--cycle;'+rect(3.1,3.6,4.3,4.7)+n(3.7,5.25,'Raccolta integrata nel tempo',w=6.6,size=11.5)+a(1.2,1.1,1.2,3.4,'Quantum')+n(1.2,4.2,'170 m',w=1.9,size=11)+n(3.7,6,'Schema non in scala.',w=6.8,size=10.5)),richiamo='La domanda deve rispettare il supporto temporale e materiale della misura disponibile.',fonti='Mikis et al., 2019; PANGAEA.902776, CC BY 4.0',origine='P02:1–3')
p('La riga rappresenta una sintesi di coppa',
'''Ogni riga contiene una sintesi degli individui analizzati nella coppa, con media, mediana, minimo e massimo del diametro massimo. La tabella selezionata non include il numero degli individui né la loro deviazione standard, per cui queste quantità non possono essere ricostruite a partire dai soli estremi. Il confronto usa medie di coppa e mantiene esplicita questa unità. Aumentare il numero di gusci misurati entro una coppa e aumentare il numero di campagne indipendenti migliorerebbe componenti differenti dell’informazione.''',tikz=d('D02',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Individui analizzati nella coppa',w=6)+a(3.7,2.1,3.7,2.7)+rect(.5,2.9,6.9,4.2,'Quantum')+n(3.7,3.55,'Media, mediana ed estremi pubblicati',w=6,size=11.5)+n(3.7,5.4,'Una riga conserva una sintesi già eseguita.',w=6.7)),richiamo='Il livello di aggregazione della fonte determina quali quantità siano identificabili dai dati.',origine='P02:4–5')
c=estratto('P02','audit',"d <- read.csv('dati/progetti/foraminiferi.csv')\nd$date <- as.Date(d$date)\nstopifnot(nrow(d)==36,\n !anyDuplicated(paste(d$trap_year,d$cup_id)),\n all(d$depth_m==170),\n all(d$diam_min_um<=d$diam_mean_um),\n all(d$diam_mean_um<=d$diam_max_um))\nhead(d)")
p('Controlli sul dizionario e sulle sintesi',
'''La coppia campagna–coppa identifica ogni riga e viene verificata prima del raggruppamento. Il codice controlla profondità, conversione delle date e ordine fra minimo, media e massimo, mantenendo le unità in micrometri. Gli estremi descrivono la dispersione degli individui osservati e non costituiscono un intervallo di confidenza della media. La data rappresenta il punto centrale attribuito alla coppa; la durata della raccolta e il flusso di gusci richiederebbero metadati ulteriori per una ponderazione temporale o quantitativa.''',codice=c,richiamo='La plausibilità delle sintesi non sostituisce le informazioni sul protocollo e sul numero degli individui.',origine='P02:5–6')
m.sezione_nuova('Copertura e definizione del confronto')
p('Due fasce calendario definite prima del calcolo',
'''La classificazione assegna ottobre, novembre, dicembre, gennaio, febbraio e marzo alla prima fascia, lasciando aprile–settembre alla seconda. Il mese viene ricavato dalla data centrale della coppa e la campagna mantiene l’identificativo fornito nella fonte. Questa regola è riproducibile, ma non misura direttamente temperatura, luce, alimento o condizioni di dissoluzione. La denominazione delle fasce conserva pertanto i mesi effettivi, evitando di trasformare il raggruppamento in una diagnosi automatica del meccanismo stagionale.''',formula=r'S_i=\begin{cases}1,&m_i\in\{10,11,12,1,2,3\},\\0,&m_i\in\{4,5,6,7,8,9\}.\end{cases}',destra='Una diversa definizione delle fasce modificherebbe il confronto e dovrebbe essere giustificata prima di osservare l’esito. Per coppe che attraversano il confine fra fasce, la data centrale è una convenzione di assegnazione, la cui sensibilità può essere studiata disponendo delle date di apertura e chiusura.',richiamo='La regola temporale definisce il confronto e mantiene distinti calendario e processo ambientale.',origine='P02:7,23')
p('L’irregolarità temporale resta visibile',
'''Le trentasei medie sono rappresentate alle rispettive date centrali senza unirle mediante una linea continua. Questa scelta conserva le lacune e la diversa densità di campionamento, evitando che il disegno suggerisca valori nei periodi privi di osservazioni. I colori distinguono le due fasce calendario, mentre la variabilità dei punti riflette insieme differenze fra coppe, campagne e condizioni di raccolta. La figura precede ogni test perché rende evidente che la composizione dei gruppi dipende dalla copertura disponibile.''',figura='P02/F01',didascalia='Trentasei medie di coppa, rappresentate alle date centrali. Le interruzioni della serie rimangono esplicite.',richiamo='La rappresentazione temporale rende riconoscibile il supporto osservativo del confronto.',origine='P02:8')
p('La matrice dei conteggi identifica le coppie',
'''La tabella grafica incrocia le sei campagne con le due fasce e riporta il numero di coppe disponibili in ogni cella. Due campagne rappresentano soltanto una fascia, mentre quattro contengono entrambe le condizioni necessarie al confronto appaiato. I conteggi differiscono anche nelle campagne complete, per cui una media su tutte le coppe attribuirebbe pesi disuguali agli anni. La selezione delle campagne complete definisce una popolazione osservativa più ristretta, della quale devono essere dichiarate composizione e ragione dell’inclusione.''',figura='P02/F02',didascalia='Numero di coppe per campagna e fascia. Una cella vuota di osservazioni è indicata da zero.',richiamo='La copertura determina quali confronti siano sostenuti dai dati e con quali pesi.',origine='P02:9,12–13')
p('Media delle coppe riunite e pesi impliciti',
'''Riunendo tutte le coppe di ciascuna fascia, la differenza risulta circa 36,66 micrometri. Il confronto Welch restituisce una probabilità di riferimento prossima a 0,004, assumendo indipendenza fra coppe e ignorando la struttura delle campagne. Questo controesempio attribuisce maggiore peso alle campagne più campionate, includendo quelle incomplete soltanto in una fascia. La quantità stimata e il modello di dipendenza differiscono quindi da quelli del confronto per campagne complete.''',formula=r'\widehat\Delta_{coppe}=\frac1{N_1}\sum_{i:S_i=1}y_i-\frac1{N_0}\sum_{i:S_i=0}y_i',destra='La differenza fra questa stima e quella appaiata riflette sia la composizione del campione sia la ponderazione. Il confronto non isola soltanto l’effetto di una diversa formula per l’errore standard, poiché cambia anche l’oggetto della media.',richiamo='Una probabilità piccola non corregge una scelta inadeguata dell’unità o della ponderazione.',origine='P02:10–11,27–28')
p('L’estimando delle campagne complete',
'''Si calcola la media delle coppe entro ogni combinazione campagna–fascia e poi la differenza ottobre–marzo meno aprile–settembre. La media finale assegna uguale peso alle quattro campagne complete, indipendentemente dal numero delle coppe. Una ponderazione per durata, individui o flusso sedimentario definirebbe un’altra quantità, che richiederebbe informazioni ulteriori.''',formula=r'\overline y_{gs}=\frac1{n_{gs}}\sum_{i\in(g,s)}y_i,\qquad d_g=\overline y_{g1}-\overline y_{g0}\\\widehat\Delta=\frac14\sum_{g=1}^{4}d_g',tikz=d('D03',rect(.5,.5,6.9,1.8)+n(3.7,1.15,'Media delle coppe entro fascia e campagna',w=6,size=11.5)+a(3.7,2,3.7,2.6)+rect(.5,2.8,6.9,4.1,'Quantum')+n(3.7,3.45,'Una differenza per campagna completa',w=6,size=11.5)+a(3.7,4.3,3.7,4.9)+n(3.7,5.5,'Media di quattro differenze equiponderate',w=6.7,size=11.5)),richiamo='Il denominatore finale è costituito dalle quattro campagne complete.',origine='P02:12–13')
c=estratto('P02','coppie',"d <- read.csv('dati/progetti/foraminiferi.csv')\nm <- as.integer(format(as.Date(d$date),'%m'))\nd$S <- ifelse(m%in%c(10:12,1:3),'S1','S0')\na <- aggregate(diam_mean_um~trap_year+S,d,mean)\nw <- reshape(a,idvar='trap_year',\n timevar='S',direction='wide')\nw <- w[complete.cases(w),]\ndelta <- w$diam_mean_um.S1-w$diam_mean_um.S0\nstopifnot(length(delta)==4)\nmean(delta)")
p('Costruzione delle coppie in R',
'''Il raggruppamento produce una riga per campagna e fascia, mentre la trasformazione in formato largo colloca le due medie sulla stessa riga. La selezione delle righe complete rende esplicito il requisito dell’appaiamento. Le etichette S1 e S0 indicano rispettivamente ottobre–marzo e aprile–settembre. Il controllo di quattro differenze e il confronto con la tabella esportata permettono di verificare che la costruzione delle coppie rispetti il protocollo dichiarato.''',codice=c,richiamo='La trasformazione della tabella deve conservare la corrispondenza fra le due medie della medesima campagna.',origine='P02:13')
p('Le quattro coppie mostrano andamenti differenti',
'''Le linee collegano le due medie della stessa campagna e rendono visibile l’eterogeneità dei confronti. Due campagne mostrano differenze negative, una una differenza positiva contenuta e una un incremento molto maggiore. Le linee descrivono un abbinamento fra medie di fascia, senza rappresentare una traiettoria continua nel tempo. Il grafico suggerisce di studiare direttamente le quattro differenze, poiché una sintesi complessiva potrebbe nascondere il contributo sproporzionato di una singola campagna.''',figura='P02/F03',didascalia='Medie delle coppe nelle quattro campagne complete. Ogni linea collega le due fasce della stessa campagna.',richiamo='La struttura appaiata rende visibile la variabilità delle differenze che entrano nell’inferenza.',origine='P02:14,16')
p('Quattro differenze come osservazioni dell’analisi',
'''Le differenze sono circa meno 5,55, più 57,35, meno 2,41 e più 10,57 micrometri, nelle quattro campagne ordinate cronologicamente. La loro media è circa 14,99 micrometri, mentre la dispersione rimane elevata rispetto a questa grandezza. La campagna 2008–2009 contribuisce in modo rilevante alla media positiva. I valori disponibili descrivono campagne di uno stesso sito e non garantiscono indipendenza temporale; tale ipotesi va discussa quando si utilizza la distribuzione delle differenze come base per un intervallo o un test.''',figura='P02/F04',didascalia='Differenza ottobre–marzo meno aprile–settembre. La linea verticale indica uguaglianza fra le due medie di fascia.',richiamo='Segno, grandezza e variabilità delle differenze precedono l’interpretazione del test.',origine='P02:15–16')
m.sezione_nuova('Incertezza con quattro unità')
p('Intervallo t sulle differenze di campagna',
'''Il test appaiato coincide con un test sulla media delle quattro differenze. L’errore standard è circa 14,55 micrometri e l’intervallo t al 95%, con tre gradi di libertà, si estende da circa meno 31,30 a più 61,28 micrometri. L’esattezza richiede differenze indipendenti e gaussiane; con quattro campagne la verifica empirica della forma distributiva rimane debole. La probabilità di riferimento, circa 0,379, riguarda questa costruzione e non esprime la probabilità che una variazione stagionale sia assente.''',formula=r'SE(\overline d)=\frac{s_d}{\sqrt4},\qquad IC_{95\%}=\overline d\pm t_{0{,}975;3}\frac{s_d}{2}',destra='L’intervallo ampio comprende differenze negative e positive di entità rilevante. La compatibilità con lo zero lascia quindi aperte molte grandezze dell’effetto e non dimostra equivalenza fra le fasce. Un’analisi di equivalenza richiederebbe limiti di rilevanza definiti e un disegno informativo adeguato.',richiamo='Con poche unità, la conclusione deve esplicitare le ipotesi e l’ampiezza dell’incertezza.',origine='P02:17–18')
p('Il confronto fra procedure cambia anche la domanda',
'''La figura accosta il confronto sulle coppe riunite e quello sulle campagne complete, con i rispettivi intervalli classici. La differenza delle stime dipende da pesi e campagne incluse, mentre la differenza dell’incertezza riflette anche l’unità scelta e le assunzioni di indipendenza. Il risultato più netto sulle coppe non offre una ragione per preferire quella procedura. La discussione identifica prima l’oggetto della media e il disegno delle osservazioni, così da scegliere un’analisi pertinente alla domanda e dichiararne i limiti.''',figura='P02/F08',didascalia='Coppe riunite: controesempio Welch. Campagne appaiate: intervallo t sulle quattro differenze. Cambiano quantità e ipotesi.',richiamo='Il confronto delle probabilità di riferimento è subordinato alla comparabilità degli estimandi.',origine='P02:10–12,18,27–28')
p('Il bootstrap conserva la campagna come unità',
'''Ogni replica estrae quattro differenze di campagna con reinserimento e ne calcola la media. I quattromila piani condivisi producono soltanto trentacinque valori distinti, perché il campione originario contiene quattro quantità e le loro combinazioni di molteplicità sono limitate. L’intervallo percentile va da circa meno 3,98 a più 42,41 micrometri. Il ricampionamento descrive la sensibilità alle campagne osservate, senza rappresentare automaticamente campagne climaticamente differenti o condizioni assenti dal sito e dal periodo considerati.''',formula=r'\overline d^{*}=\frac14\sum_{r=1}^{4}d_{I_r},\qquad I_r\in\{1,2,3,4\}',figura='P02/F05',didascalia='Quattromila repliche su quattro campagne. La distribuzione è discreta; le linee viola indicano i quantili percentili.',richiamo='Il ricampionamento rende esplicita la variabilità del campione disponibile senza crearne nuove unità.',origine='P02:19–20')
p('Ribaltamento dei segni e ipotesi di simmetria',
'''Un controllo ulteriore conserva le grandezze delle differenze e ne enumera i possibili segni. Con quattro differenze si ottengono sedici configurazioni, considerate equiprobabili sotto un’ipotesi di simmetria e indipendenza dei segni rispetto alla nullità dell’effetto. Nel disegno osservativo non è avvenuta una randomizzazione dei segni: l’interpretazione dipende quindi da questa ipotesi di riferimento. Otto configurazioni hanno una media in valore assoluto almeno pari a quella osservata, producendo una probabilità bilaterale di un mezzo.''',formula=r'T(s)=\frac14\sum_{g=1}^{4}s_gd_g,\qquad s_g\in\{-1,+1\}',tikz=d('D04',''.join(rect(.45+(k%4)*1.75,.5+(k//4)*1.3,2.0+(k%4)*1.75,1.45+(k//4)*1.3,'Quantum' if abs(sum(a*b for a,b in zip(ss,[-5.55,57.353333333333,-2.41,10.57]))/4)>=14.99083333333-1e-8 else 'Classical')+n(1.225+(k%4)*1.75,.975+(k//4)*1.3,r'\texttt{'+''.join('+' if z>0 else '-' for z in ss)+'}',size=12) for k,ss in enumerate(itertools.product([-1,1],repeat=4)))+n(3.7,5.85,'Viola: otto esiti estremi.',w=6.9,size=10.7)),richiamo='L’enumerazione è esatta per il riferimento scelto, la cui pertinenza al disegno osservativo deve essere motivata.',origine='P02:21')
p('La risoluzione del test dipende dal disegno',
'''La distribuzione di riferimento contiene sedici masse di probabilità uguali a un sedicesimo. La simmetria associa a ogni configurazione quella con tutti i segni invertiti, per cui il più piccolo valore bilaterale possibile è due sedicesimi, pari a 0,125, quando le due configurazioni estreme sono uniche. Una maggiore precisione numerica del calcolo non supera questo limite, che deriva dal numero delle unità e dal riferimento utilizzato. Nel caso osservato la probabilità è 0,5, coerentemente con le otto configurazioni evidenziate.''',formula=r'p=\frac{\#\{|T(s)|\geq|\overline d|\}}{16}=\frac8{16}=0{,}5',figura='P02/F06',didascalia='Distribuzione delle medie sotto i sedici cambi di segno. Ocra: configurazioni almeno altrettanto estreme dell’osservata.',richiamo='La risoluzione inferenziale deriva dal disegno e resta distinta dalla precisione aritmetica.',origine='P02:21')
p('Sensibilità alla singola campagna',
'''L’omissione di una campagna alla volta produce medie comprese fra circa 0,87 e 21,84 micrometri. Escludendo il 2008–2009, la differenza media si avvicina allo zero, rendendo evidente il contributo di quell’anno alla sintesi complessiva. Questa diagnosi orienta l’esame della copertura e delle condizioni ambientali, senza fornire da sola una motivazione per eliminare la campagna. La relazione deve conservare il risultato sul campione completo e discutere le alternative attraverso evidenze indipendenti dalla convenienza della conclusione.''',figura='P02/F07',didascalia='Media delle tre differenze rimaste dopo ogni omissione. La linea viola indica la media sulle quattro campagne.',richiamo='L’influenza di una campagna orienta il controllo del disegno e del contesto, prima di qualsiasi esclusione.',origine='P02:22')
m.sezione_nuova('Interpretazione e nuova raccolta')
p('Dal calendario alle ipotesi ambientali',
'''Le fasce temporali possono essere associate a condizioni differenti di produzione, nutrimento, trasporto e conservazione dei gusci, ma il confronto delle medie non distingue questi meccanismi. Una sola posizione geografica e quattro campagne complete delimitano ulteriormente l’argomento. Il risultato sostiene una descrizione della differenza nelle campagne disponibili, accompagnata da un’incertezza ampia e da sensibilità fra anni. Per studiare il meccanismo servirebbero misure ambientali concomitanti e un disegno che colleghi tali variazioni alle proprietà morfometriche osservate.''',tikz=d('D05',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Fascia calendario osservata',w=6)+a(2,2.1,2,3)+a(5.4,2.1,5.4,3,'Quantum')+rect(.4,3.2,3.5,4.7)+n(1.95,3.95,'Produzione e crescita',w=2.8,size=11.5)+rect(3.9,3.2,7,4.7,'Quantum')+n(5.45,3.95,'Trasporto e conservazione',w=2.8,size=11.5)+n(3.7,5.6,'Meccanismi da distinguere con dati ulteriori',w=6.8,size=11.5)),richiamo='Il raggruppamento temporale descrive un confronto e lascia aperta l’identificazione dei meccanismi.',origine='P02:23–24')
p('Progettare una copertura più informativa',
'''Una raccolta successiva dovrebbe migliorare la copertura delle due fasce in più campagne, documentando intervalli di apertura delle coppe, numero di individui, dispersione delle misure e flusso sedimentario. Queste informazioni permetterebbero di definire ponderazioni coerenti con la quantità scientifica di interesse e di separare l’incertezza interna alle coppe dalla variabilità fra campagne. Ulteriori siti amplierebbero il dominio geografico, purché la loro selezione e i protocolli fossero comparabili. Il miglioramento del disegno riguarda pertanto livelli diversi della gerarchia osservativa.''',tikz=d('D06',rect(.5,.5,6.9,1.8)+n(3.7,1.15,'Individui: numerosità e dispersione',w=6)+rect(.5,2.5,6.9,3.8,'Quantum')+n(3.7,3.15,'Coppe: durata, copertura e flusso',w=6)+rect(.5,4.5,6.9,5.8,'Measure')+n(3.7,5.15,'Campagne e siti: nuove unità di confronto',w=6,size=11.5)),richiamo='La raccolta aggiuntiva va progettata rispetto alla componente di incertezza che si vuole ridurre.',origine='P02:25,29')
p('Relazione e discussione del confronto',
'''La consegna include matrice della copertura, grafico delle coppie, definizione della differenza, intervallo t, bootstrap, controllo dei segni e sensibilità alle campagne. L’esercizio confronta il risultato sulle coppe riunite con quello appaiato, spiegando come cambino pesi, campione e assunzioni. Una risposta adeguata mantiene distinti assenza di evidenza netta, equivalenza fra fasce e identificazione di un meccanismo. Codice, dati e attribuzioni consentono di ricostruire il procedimento e di proporre una nuova raccolta coerente con i limiti emersi.''',destra='R/P02_figure.R produce le figure e le tabelle a partire dall’estratto conservato in dati/progetti. La fonte è Mikis et al. (2019), PANGAEA.902776, distribuita con licenza CC BY 4.0. Il progetto raccorda campionamento gerarchico, inferenza sulla media e test appaiati dei moduli M01, M05 e M06.',richiamo='La relazione sostiene la conclusione attraverso il disegno osservativo, oltre che attraverso i risultati numerici.',fonti='Mikis et al., 2019, PANGAEA.902776; CC BY 4.0',origine='P02:26–30')
m.salva()
